function CommodityDecisionScreen({thesis,evidence}){return <><section className="commodity-thesis"><header><div><span>COMMODITY DECISION FRAME</span><h2>{thesis.stance}</h2><p>{thesis.debate}</p></div><aside><small>CONFIDENCE</small><b>{thesis.confidence}</b><small>HORIZON</small><b>{thesis.horizon}</b></aside></header><div><article><span>BASE CASE</span><p>{thesis.base}</p></article><article><span>FORECAST LOGIC</span><p>{thesis.forecast}</p></article></div></section><section className="commodity-scorecard"><header><span>BALANCE SCORECARD</span><h3>What the available evidence says</h3></header><div>{thesis.score.map(([factor,signal,evidence])=><article key={factor}><span>{factor}</span><b className={/bearish|loosening/i.test(signal)?"negative":/constructive|tight|approaching/i.test(signal)?"positive":"neutral"}>{signal}</b><p>{evidence}</p></article>)}</div><div className="commodity-evidence-table"><div><span>Factor / observation</span><span>Value</span><span>Period / change</span><span>Interpretation</span><span>Evidence</span></div>{evidence.map((x,i)=><article key={`${x.metric}-${x.period}-${i}`}><b>{x.factor}<small>{x.metric}</small></b><strong>{x.value}</strong><span>{x.period}<small>{x.change}</small></span><p>{x.meaning}</p><em className={x.status==="data gap"?"gap":""}>{x.status}{x.url&&<a href={x.url} target="_blank" rel="noreferrer">{x.source} ↗</a>}</em></article>)}</div></section><section className="commodity-scenarios"><header><span>SCENARIO MAP</span><h3>What would produce a different outcome?</h3></header><div>{thesis.scenarios.map(([name,event,confirmation])=><article className={name.toLowerCase()} key={name}><span>{name.toUpperCase()}</span><b>{event}</b><p>{confirmation}</p></article>)}</div></section><section className="commodity-trigger-calendar"><header><span>MONITORING CALENDAR</span><h3>Next evidence that can change the view</h3></header><div>{thesis.triggers.map(([cadence,indicator,use])=><article key={`${cadence}-${indicator}`}><span>{cadence}</span><b>{indicator}</b><p>{use}</p></article>)}</div></section></>}
function CommodityEvidencePanel({thesis,evidence}){return <section className="commodity-scorecard evidence-only"><header><span>DATED EVIDENCE</span><h3>Observations behind the balance assessment</h3></header><div>{thesis.score.map(([factor,signal,evidence])=><article key={factor}><span>{factor}</span><b className={/bearish|loosening/i.test(signal)?"negative":/constructive|tight|approaching/i.test(signal)?"positive":"neutral"}>{signal}</b><p>{evidence}</p></article>)}</div><div className="commodity-evidence-table"><div><span>Factor / observation</span><span>Value</span><span>Period / change</span><span>Interpretation</span><span>Evidence</span></div>{evidence.map((x,i)=><article key={`${x.metric}-${x.period}-${i}`}><b>{x.factor}<small>{x.metric}</small></b><strong>{x.value}</strong><span>{x.period}<small>{x.change}</small></span><p>{x.meaning}</p><em className={x.status==="data gap"?"gap":""}>{x.status}{x.url&&<a href={x.url} target="_blank" rel="noreferrer">{x.source} ↗</a>}</em></article>)}</div></section>}
