function IronOreTraderWorkstation({atlas}){
  const [priceShock,setPriceShock]=useState(10);
  const china=atlas.country_profiles?.find(c=>c.id==="chn"),metric=id=>china?.metrics?.find(m=>m.metric===id),fmt=m=>m?`${Number(m.value).toLocaleString(undefined,{maximumFractionDigits:1})} ${m.unit||""}`:"Feed pending";
  const oreRoutes=(atlas.shipping_routes||[]).filter(r=>r.commodity_id==="iron-ore"),oreAssets=(atlas.assets||[]).filter(a=>a.commodity_id==="iron-ore");
  const balance=[
    ["China hot-metal / BF demand","High frequency","Primary demand impulse","Daily/weekly feed pending"],
    ["China iron-ore imports","Monthly",fmt(metric("iron_ore_imports")),metric("iron_ore_imports")?.period||"Latest Atlas vintage"],
    ["Domestic Chinese ore supply","Monthly",fmt(metric("iron_ore_production")),metric("iron_ore_production")?.period||"Latest Atlas vintage"],
    ["Australia + Brazil shipments","Weekly","Core seaborne supply","Vessel feed pending"],
    ["China port inventories","Weekly","Restocking / destocking signal","Inventory feed pending"],
    ["Implied seaborne balance","Monthly","Derived after feed connection","Method ready"]
  ];
  const sensitivities=[
    ["China hot-metal output","HIGH","Moves ore consumption directly; BF utilization matters more than crude-steel headlines."],
    ["Steel mill margins","HIGH","Positive margins support utilization and higher-grade feed demand."],
    ["Port stocks + restocking","HIGH","Separates apparent import strength from underlying consumption."],
    ["Australia / Brazil outages","MEDIUM–HIGH","Weather and maintenance can tighten prompt cargo availability."],
    ["Freight and producer FX","MEDIUM","Changes delivered spreads and miners' local-currency margins."],
    ["New projects incl. Simandou","LOW NEAR TERM","One component of the multi-year supply pipeline; ramp timing and displacement matter more than nameplate capacity."]
  ];
  const producers=[
    {name:"Rio Tinto",volume:330.5,volumeLabel:"323–338 Mt guidance midpoint",period:"2025 guidance · Pilbara 100% basis",price:"Not shown",cost:"US$24.3/wmt",costLabel:"H1 2025 FOB cash cost",focus:"Pilbara volume, blend, AUD and replacement capex",source:"https://www.riotinto.com/-/media/content/documents/invest/financial-news-and-performance/results/2025/2025-hy-results.pdf?rev=91689f655b24429b826938a1315d2eb2"},
    {name:"BHP",volume:254.813,volumeLabel:"254.8 Mt sales",period:"FY2025 · equity-share sales",price:"US$82.13/wmt",cost:"US$18.56/t",costLabel:"WAIO unit cost",focus:"Realization, WAIO reliability, AUD and capital returns",source:"https://www.bhp.com/ar2025_note4"},
    {name:"Vale",volume:314,volumeLabel:"314 Mt sales",period:"CY2025 · company sales",price:"US$95.4/t",priceLabel:"Q4 fines only",cost:"US$21.3/t",costLabel:"2025 C1 cash cost",focus:"Quality premium, Brazil freight, BRL and product mix",source:"https://vale.com/documents/d/guest/2025_annual-report_14042026"},
    {name:"Fortescue",volume:198.4,volumeLabel:"198.4 Mt shipped",period:"FY2025 · total shipments",price:"Not shown",cost:"US$18.50–19.75/wmt",costLabel:"FY2025 guidance range",focus:"Discount realization, C1 cost, freight and growth capex",source:"https://investors.fortescue.com/en/results-and-operational-performance"}
  ];
  return <section className="iron-workstation"><header><div><span>IRON-ORE TRADER WORKSTATION · WORKED EXAMPLE</span><h2>Demand, prompt balance and producer earnings</h2><p>The decision frame prioritizes the variables that repeatedly move the market. Long-dated projects are monitored, but do not dominate the base thesis.</p></div><aside><b>Current stance</b><strong>Data-building · neutral</strong><small>Price feed and weekly physical indicators still required</small></aside></header>
    <h3>Physical balance monitor</h3><div className="balance-table"><div><span>Component</span><span>Frequency</span><span>Current evidence</span><span>Vintage / status</span></div>{balance.map(r=><article key={r[0]}>{r.map((x,i)=><span key={i}>{x}</span>)}</article>)}</div>
    <div className="workstation-grid"><section><h3>What matters most</h3>{sensitivities.map(([name,weight,why])=><article key={name}><header><b>{name}</b><span className={`weight-${weight.split("–")[0].toLowerCase().replace(" ","")}`}>{weight}</span></header><p>{why}</p></article>)}</section><section><h3>Physical Atlas coverage</h3><div className="coverage-numbers"><article><b>{oreAssets.length}</b><span>ore-linked assets</span></article><article><b>{oreRoutes.length}</b><span>maritime routes</span></article><article><b>{atlas.flows?.filter(f=>f.commodity_id==="iron-ore").length||0}</b><span>bilateral flows</span></article></div><p className="coverage-meaning">Coverage shows what is structured in the Atlas, not the total real-world market. Zero or low counts identify collection gaps.</p><h3>Required next feeds</h3><ul><li>Daily 62% Fe benchmark and SGX curve</li><li>Weekly China port stocks and arrivals</li><li>Weekly Australia/Brazil shipments</li><li>Daily blast-furnace utilization and steel margins</li><li>Capesize C3/C5 freight assessments</li></ul></section></div>
    <div className="producer-heading"><div><h3>Producer and equity read-through</h3><p>Comparable operating disclosures plus a deliberately simple benchmark-price transmission test.</p></div><label><span>BENCHMARK MOVE</span><b>{priceShock>0?"+":""}{priceShock} US$/t</b><input type="range" min="-30" max="30" step="5" value={priceShock} onChange={e=>setPriceShock(Number(e.target.value))}/></label></div>
    <div className="producer-table"><div className="producer-table-head"><span>Producer / scope</span><span>Sales or shipments</span><span>Realized price</span><span>Disclosed cost</span><span>Gross revenue sensitivity</span></div>{producers.map(p=><article key={p.name}><span><b>{p.name}</b><small>{p.period}</small></span><span><b>{p.volumeLabel}</b><small>{p.focus}</small></span><span><b>{p.price}</b><small>{p.priceLabel||"Reporting basis varies"}</small></span><span><b>{p.cost}</b><small>{p.costLabel}</small></span><span className={priceShock>=0?"positive":"negative"}><b>{priceShock>=0?"+":"−"}US${Math.abs(p.volume*priceShock/1000).toFixed(2)}bn</b><small>{p.volume.toFixed(1)} Mt × {Math.abs(priceShock)} US$/t · <a href={p.source} target="_blank" rel="noreferrer">source ↗</a></small></span></article>)}</div>
    <div className="sensitivity-method"><b>How to read this</b><p>Gross revenue sensitivity = disclosed sales or shipment volume × benchmark-price move. It is a first-pass exposure measure, not EBITDA, free cash flow or valuation. It does not deduct royalties, freight, premiums or discounts, price-linked costs, taxes, minority interests, hedges, volume changes or currency effects. Rio’s figure is explicitly a 100%-basis Pilbara system estimate; Vale’s displayed realized price is Q4 fines rather than a full-year average; Fortescue’s cost remains a guidance range.</p></div>
    <h3>Catalyst calendar</h3><div className="catalyst-strip">{[["DAILY","Benchmark, futures curve, steel margins"],["WEEKLY","Port stocks, shipments, BF utilization, freight"],["MONTHLY","China customs, steel output, PMI and property"],["QUARTERLY","Miner production, realized prices, costs and guidance"],["ANNUAL / PROJECT","Mine depletion, expansions and new supply ramps"]].map(([freq,event])=><article key={freq}><span>{freq}</span><b>{event}</b></article>)}</div>
    <footer><a href="https://www.worldbank.org/en/research/commodity-markets" target="_blank" rel="noreferrer">World Bank commodity history ↗</a><a href="https://www.cmegroup.com/markets/metals/ferrous/iron-ore-62-cfr-china-tsi-swap-futures.html" target="_blank" rel="noreferrer">CME iron-ore contract ↗</a><small>Producer disclosures use different reporting periods and scopes. The table preserves those differences instead of presenting the estimates as directly comparable earnings forecasts.</small></footer>
  </section>
}

