function CompanyDirectory({companies}) {
  const requested=String(window.__atlasDestination?.context||"").toLowerCase();
  const [industry,setIndustry]=useState("All industries");
  const [selected,setSelected]=useState(()=>companies.find(c=>c.id===requested||c.name?.toLowerCase()===requested)||null);
  const [finance,setFinance]=useState(null);
  const groups={"Mining & materials":["Mining","Nickel mining","Nickel mining and processing"],Steel:["Steel"],Batteries:["Battery manufacturing"],Automotive:["EV and battery","EV manufacturing"],Shipbuilding:["Shipbuilding"],"Data Centers":["Data center infrastructure"]};
  const liveCompanies=new Set(["rio","arcelormittal","catl","byd","hd-hyundai-shipbuilding","cleveland-cliffs","equinix"]);
  const groupFor=value=>Object.entries(groups).find(([,items])=>items.includes(value))?.[0]||"Other industrials";
  const industries=["All industries",...Object.keys(groups),"Other industrials"];
  const shown=companies.filter(c=>industry==="All industries"||groupFor(c.industry)===industry);
  useEffect(()=>{if(!selected&&requested){const match=companies.find(c=>c.id===requested||c.name?.toLowerCase()===requested);if(match)setSelected(match)}},[companies.length,requested]);
  useEffect(()=>{if(!selected){setFinance(null);return}setFinance(null);fetch(`/api/companies/${selected.id}/finance`).then(r=>r.ok?r.json():null).then(setFinance).catch(()=>setFinance(null))},[selected?.id]);
  if(selected){const full=["byd","cleveland-cliffs","equinix","rio","arcelormittal","catl","hd-hyundai-shipbuilding"].includes(selected.id);return <div className="standard-company-page"><ResearchStandard company={selected} full={full}/>{selected.id==="byd"?<CompanyFinance company={selected} data={finance} onBack={()=>setSelected(null)}/>:<SectorCompanyProfile company={selected} data={finance} onBack={()=>setSelected(null)}/>}</div>}
  return <section className="directory-page"><PageTitle icon={Building2} title="Equity research" subtitle="Company conclusions linked to financial models, expectations, industrial evidence and explicit thesis-break conditions"/>
    <div className="research-mode-explainer"><article><span>SELL-SIDE DISCIPLINE</span><b>Forecast, valuation and audit trail</b><p>Reported results, company guidance, estimates, valuation methods, target logic and sources remain explicit and reproducible.</p></article><i>+</i><article><span>BUY-SIDE OVERLAY</span><b>Variant view, expectations and action rules</b><p>Every report identifies the debate, what differs from the market narrative, the next catalyst and evidence that would invalidate the thesis.</p></article><i>=</i><article><span>ATLAS OUTPUT</span><b>Physical evidence linked to an investable conclusion</b><p>Macro and supply-chain signals change model assumptions only through a documented earnings-transmission mechanism.</p></article></div>
    <section className="coverage-dashboard"><header><div><span>ACTIVE RESEARCH COVERAGE</span><h2>Long, short or wait?</h2></div><p>Stance is the research conclusion—not a simulated holding. Open a company to inspect the evidence and assumptions behind it.</p></header><div className="coverage-table"><div><span>Company</span><span>Industry</span><span>Stance</span><span>Conviction</span><span>Revision trend</span><span>Next catalyst</span></div>{researchCoverage.map(item=>{const row=companies.find(c=>c.id===item.id);if(!row)return null;const stanceClass=item.stance.startsWith("LONG")||item.stance.startsWith("CONSTRUCTIVE")?"long":item.stance.includes("→")?"watch":"neutral";return <button key={item.id} onClick={()=>setSelected(row)}><b>{row.name}</b><span>{groupFor(row.industry)}</span><strong className={stanceClass}>{item.stance}</strong><span>{item.conviction}</span><em className={item.revision.toLowerCase()==="positive"||item.revision.toLowerCase()==="improving"?"positive":"neutral"}>{item.revision}</em><small>{item.catalyst}<i>{item.status}</i></small></button>})}</div></section>
    <div className="company-industry-tabs">{industries.map(name=><button key={name} className={industry===name?"active":""} onClick={()=>setIndustry(name)}>{name}</button>)}</div>
    {Object.keys(groups).concat("Other industrials").filter(group=>industry==="All industries"||industry===group).map(group=>{const rows=shown.filter(c=>groupFor(c.industry)===group);return rows.length?<div className="company-sector" key={group}><header><h2>{group}</h2><span>{rows.length} companies</span></header><div className="entity-grid">{rows.map(row=>{const live=liveCompanies.has(row.id);return <button className={`entity-card company-card ${live?"company-live":"company-backlog"}`} key={row.id} onClick={()=>live&&setSelected(row)} aria-disabled={!live}><div className="card-top"><span className="entity-dot"/><span>{row.country||"Global"} · {row.industry}</span></div><h3>{row.name}</h3><p>{live?"Institutional report · conclusion, estimates, valuation, catalysts and Atlas evidence":"Research backlog · profile not yet published"}</p><div className="card-stats"><span><b>{row.asset_count||0}</b> assets</span><span className={live?"finance-live":""}>{live?"LIVE":"RESEARCH QUEUE"}</span></div></button>})}</div></div>:null})}
  </section>;
}

