  ["01","Conclusion","Long / short / watch"],["02","Financials","Reported operating snapshot"],["03","Debate","Thesis and variant perception"],["04","Forecast","Driver-based forward model"],["05","Expectations","Guidance and revisions"],["06","Valuation","Base, bull and bear"],["07","Atlas evidence","Physical-chain transmission"],["08","Monitoring","Catalysts and thesis breaks"]
